    cols = len(grid[0])
    output = [list(row) for row in grid]

    # Determine colors from the grid
    # Find most frequent color as background
    from collections import Counter
    colors = Counter()
    for r in range(rows):
        for c in range(cols):
            colors[grid[r][c]] += 1

    bg = colors.most_common(1)[0][0]
    others = [c for c, v in colors.items() if c != bg]

    # Identify wall (edge color) and marker (interior color)
    wall = None
    marker = None
    for c in others:
        # Check if this color is on left or right edge
        found_edge = any(grid[r][0] == c or grid[r][cols-1] == c for r in range(rows))
        if found_edge:
            wall = c
            break

    if wall is not None:
        marker = [c for c in others if c != wall][0]
    else:
        marker = others[0]

    for r in range(rows):
        # Find positions
        has_left_wall = grid[r][0] == wall
        has_right_wall = grid[r][cols - 1] == wall
        marker_pos = -1

        for c in range(cols):
            if grid[r][c] == marker:
                marker_pos = c
                break

        if has_right_wall:
            if marker_pos != -1:
                # Source row with right wall: fill BETWEEN marker and wall
